_V39_POLICY = _V39_PLANNER.build_hierarchical_policy(
    _V39_BASE.agent, _V39_WOOL.agent, _V39_ALT.agent, _V39_CALIBRATION
)


def agent(obs, configuration=None):
    try:
        return _V39_POLICY(obs, configuration)
    except Exception:
        seat = 1 if int(obs.get("player", 0) or 0) == 1 else 0
        farms = list(obs.get("farms", []) or [])
        farm = farms[seat] if seat < len(farms) else {}
        return {
            "farmer": ["PASS"],
            "hands": [["PASS"] for _ in (farm.get("hands", []) or [])],
            "market": [],
        }


def _kaggle_submission_entrypoint(obs, configuration=None):
    return agent(obs, configuration)
